INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kann ich Schulungen ohne Zielgruppe anbieten?', 2, '[{"text": "Nein", "correct": true, "because": "Zielgruppe definiert Inhalt"}, {"text": "Ja", "correct": false, "because": "Fehlende Relevanz"}]'),
