('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Schulungen?', 4, '[{"text": "Lernziele", "correct": false, "because": "Definiert Erfolg"}, {"text": "Teilnehmerbedarf", "correct": false, "because": "Passt Inhalt an"}, {"text": "Schriftfarbe", "correct": true, "because": "Irrelevant"}]'),
