('00000000-0000-0000-0000-000000000000', 'Welches Format wähle ich für Admin-Schulungen?', 3, '[{"text": "Hands-on", "correct": true, "because": "Praxisnah für Admins"}, {"text": "Nur Theorie", "correct": false, "because": "Zu abstrakt"}, {"text": "E-Mail", "correct": false, "because": "Keine Interaktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Schulungen effektiv?', 5, '[{"text": "Relevanz", "correct": true, "because": "Passt an Bedarf"}, {"text": "Feedback", "correct": true, "because": "Verbessert Lernen"}, {"text": "Hohe Kosten", "correct": false, "because": "Kein Qualitätsmerkmal"}, {"text": "Lange Dauer", "correct": false, "because": "Ermüdend"}]'),
